int ans = INT_MIN;
int gain(TreeNode* r) {
    if (!r) return 0;
    int L = max(0, gain(r->left));      // refuse poison
    int R = max(0, gain(r->right));
    ans = max(ans, r->val + L + R);     // through-path (both arms)
    return r->val + max(L, R);          // downward arm only
}

// SER: N,L,R with # for nulls, space-separated
void ser(TreeNode* r, string& o){
    if(!r){ o += "# "; return; }
    o += to_string(r->val)+' ';
    ser(r->left,o); ser(r->right,o);
}
// DESER: queue consumes tokens in same order
TreeNode* des(queue<string>& q){
    string t = q.front(); q.pop();
    if (t == "#") return nullptr;
    TreeNode* r = new TreeNode(stoi(t));
    r->left = des(q); r->right = des(q);
    return r;
}
